import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useAnimation } from './AnimationQueue';
import { processText } from '../utils/textUtils';

interface AnimatedTextProps {
  text: string;
  element?: 'p' | 'h1' | 'h2' | 'h3' | 'h4' | 'span' | 'div' | 'li' | 'a';
  className?: string;
  preserveWhitespace?: boolean;
  onComplete?: () => void;
  delay?: number;
  priority?: number;
  dependencies?: string[];
  name?: string; // Add name for easier dependency tracking
}

const DEBUG = false;

/**
 * AnimatedText component that renders text character by character
 * Uses the animation queue system for coordinated animations
 */
const AnimatedText: React.FC<AnimatedTextProps> = ({
  text,
  element = 'span',
  className = '',
  preserveWhitespace = false,
  onComplete,
  delay = 0,
  priority = 0,
  dependencies = [],
  name
}) => {
  const [visibleChars, setVisibleChars] = useState(0);
  const [isComplete, setIsComplete] = useState(false);
  const [isAnimating, setIsAnimating] = useState(false);
  const animationIdRef = useRef<string | null>(null);

  // Process text content
  const processedText = processText(text, preserveWhitespace);

  // Get animation context
  const { registerAnimation, completeAnimation } = useAnimation();

  // Register with animation queue on mount
  useEffect(() => {
    if (!processedText) return;

    const handleStart = () => {
      if (DEBUG) console.log(`Starting text animation: ${name || 'unnamed'}`);
      setVisibleChars(0);
      setIsComplete(false);
      setIsAnimating(true);
    };

    const handleComplete = () => {
      if (DEBUG) console.log(`Completed text animation: ${name || 'unnamed'}`);
      if (onComplete) {
        onComplete();
      }
    };

    // Register this animation with the queue
    const animationId = registerAnimation('text', {
      priority,
      dependencies,
      onStart: handleStart,
      onComplete: handleComplete,
      name
    });

    animationIdRef.current = animationId;

    // Clean up
    return () => {
      if (animationIdRef.current && isAnimating && !isComplete) {
        completeAnimation(animationIdRef.current);
      }
    };
  }, [
    processedText, 
    priority, 
    dependencies, 
    registerAnimation, 
    completeAnimation, 
    onComplete, 
    name, 
    isAnimating, 
    isComplete
  ]);

  // Handle actual animation when active
  useEffect(() => {
    if (!isAnimating || !animationIdRef.current) return;

    let timeout: NodeJS.Timeout;
    let charIndex = 0;

    const animateNextChar = () => {
      if (charIndex < processedText.length) {
        charIndex++;
        setVisibleChars(charIndex);

        // Calculate next delay - longer for punctuation
        let charDelay = 20; // Faster base delay

        // Slow down for punctuation
        const currentChar = processedText[charIndex - 1];
        if (['.', '!', '?'].includes(currentChar)) {
          charDelay = 100; // Moderate pause after major punctuation
        } else if ([',', ';', ':'].includes(currentChar)) {
          charDelay = 50; // Brief pause after minor punctuation
        }

        // Smaller random variation
        charDelay += Math.random() * 10 - 5;

        // Add any external delay, but only for the first character
        const totalDelay = charDelay + (charIndex === 1 ? delay : 0);

        timeout = setTimeout(animateNextChar, totalDelay);
      } else {
        setIsComplete(true);
        setIsAnimating(false);

        // Signal completion to the animation queue
        if (animationIdRef.current) {
          if (DEBUG) console.log(`Text animation complete: ${name || 'unnamed'}`);
          completeAnimation(animationIdRef.current);
        }
      }
    };

    // Start the animation sequence with minimal delay
    timeout = setTimeout(animateNextChar, 30);

    // Fallback to ensure text is fully visible if animation stalls
    // Only trigger after a significant delay to avoid interrupting normal animation
    const fallbackTimer = setTimeout(() => {
      if (!isComplete && visibleChars < processedText.length) {
        if (DEBUG) console.log(`Fallback triggered for text: ${name || 'unnamed'}`);
        setVisibleChars(processedText.length);
        setIsComplete(true);
        setIsAnimating(false);
        if (animationIdRef.current) {
          completeAnimation(animationIdRef.current);
        }
      }
    }, 10000); // 10 second fallback - only for real issues

    return () => {
      clearTimeout(timeout);
      clearTimeout(fallbackTimer);
    };
  }, [
    processedText, 
    delay, 
    isAnimating, 
    completeAnimation, 
    isComplete, 
    visibleChars, 
    name
  ]);

  // Create array of characters with animated wrappers
  const animatedChars = processedText.split('').map((char, index) => {
    const isVisible = index < visibleChars;

    return (
      <AnimatePresence key={index} mode="wait">
        {isVisible && (
          <motion.span
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.08 }} // Slightly faster transition
            style={{ 
              display: 'inline-block',
              whiteSpace: preserveWhitespace ? 'pre' : 'normal'
            }}
          >
            {char}
          </motion.span>
        )}
      </AnimatePresence>
    );
  });

  // Component-specific styles
  const componentStyle = {
    display: 'inline-block', // Changed to inline-block for better text flow
    whiteSpace: preserveWhitespace ? 'pre-wrap' as const : 'normal' as const,
    wordBreak: 'break-word' as const
  };

  // Render with specified element type
  const Component = element as any;

  // Always show full text in a no-JS/disabled state to ensure content is accessible
  if (visibleChars === 0 && !isAnimating && processedText.length > 0) {
    return (
      <Component 
        className={`animated-text ${className} no-animation`}
        style={componentStyle}
      >
        {processedText}
      </Component>
    );
  }

  return (
    <Component 
      className={`animated-text ${className} ${isComplete ? 'complete' : ''}`}
      style={componentStyle}
    >
      {animatedChars}
    </Component>
  );
};

export default AnimatedText;
